import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import vm from 'node:vm';

// Execute the pure calculation modules without the browser bundler.
const context=vm.createContext({});
for(const file of ['monthlyForecast','advancedCalculations','mortgageCalculations']) {
    const source=readFileSync(new URL(`../src/components/${file}.js`,import.meta.url),'utf8').replace(/^import .*?;\s*/gm,'').replaceAll('export ','');
    vm.runInContext(source,context,{filename:file});
}
// Reference scalar outputs were generated by backend/advanced_analysis.py.
const cases=JSON.parse(readFileSync(new URL('./fixtures/analysis-parity.json',import.meta.url),'utf8'));
for(const [index,scenario] of cases.entries()) {
    test(`${scenario.mode} server/client parity ${index+1}`,()=>{
        const actual=(scenario.mode==='cash'?context.calculateAdvanced:context.calculateMortgage)(scenario.inputs);
        for(const [key,value] of Object.entries(scenario.expected)) {
            if(value===null) assert.equal(actual[key],null,key);
            else assert.ok(Number.isFinite(actual[key]) && Math.abs(value-actual[key])<=Math.max(0.0001,Math.abs(value)*1e-8),`${key}: ${actual[key]} vs ${value}`);
        }
    });
}
